<include file="Publics:header"/>	<div class="mainbox">        <div class="form-group">            <label class="col-sm-1" style="width: 15%;"><label for="diy_village_name">是否显示系统导航</label></label>            <div class="radio" style="padding-top: 5px;">                <label style="padding-left:0px;padding-right:20px;"><input name="read_idcard" value="1" type="radio" class="ace" <if condition="($village_nav.village_nav eq 1 && $row_type neq single) || ($village_nav.village_nav_single eq 1 && $row_type eq single)">checked</if>/><span class="lbl" style="z-index: 1">开启</span></label>                <label style="padding-left:0px;"><input name="read_idcard" value="0" type="radio" class="ace" <if condition="($village_nav.village_nav eq 0 && $row_type neq single) || ($village_nav.village_nav_single eq 0 && $row_type eq single)">checked</if>/><span class="lbl" style="z-index: 1">关闭</span></label>            </div>        </div>		<!--目前需求不明，前端未做处理，先暂时隐藏此功能-->		<!--<if condition="$yingshan">			<div class="form-group">				<label class="col-sm-1" style="width: 15%;"><label for="diy_village_name"><if condition="$row_type neq single">单行</if>功能导航效果</label></label>				<div class="radio" style="padding-top: 5px;">					<label style="padding-left:0px;padding-right:20px;"><input name="multiline_effect" value="1" type="radio" class="ace" <if condition="($village_nav.single_effect eq 1 && $row_type neq single) || ($village_nav.multiline_effect eq 1 && $row_type eq single)">checked</if>/><span class="lbl" style="z-index: 1">开启</span></label>					<label style="padding-left:0px;"><input name="multiline_effect" value="0" type="radio" class="ace" <if condition="($village_nav.single_effect eq 0 && $row_type neq single) || ($village_nav.multiline_effect eq 0 && $row_type eq single)">checked</if>/><span class="lbl" style="z-index: 1">关闭</span></label>					<if condition="$row_type eq single">开通后，页面单行功能导航展示功能导航的效果<else/>开通后，页面功能导航展示单行功能导航的效果</if>				</div>			</div>		</if>-->		<if condition="$row_type eq single">			<div class="form-group">				<label class="col-sm-1" style="width: 15%;"><label for="diy_village_name">一屏展示数量</label></label>				<div class="select" style="padding-top: 5px;">					<select class="col-sm-1" id="view_num" name="view_num">						<option value="5" <if condition="$village_nav.view_num eq 5">selected</if>>5</option>						<option value="7" <if condition="$village_nav.view_num eq 7">selected</if>>7</option>					</select>					<span class="form_tips">选择后，单行功能导航一行展示的数量(与功能导航效果设置无关)</span>				</div>			</div>		</if>        <div style="margin-left: 10px;color: #9a9999">            <span> 说明：</span>            <p>1.开关按钮默认开启</p>            <p> 2.当开关是开启状态下，即默认<?php echo (D('House_village')->getHouseAlias('house_name',$village_id)?:'小区')?>里的正常导航大于或等于{pigcms{$show_nav_count}个的时候显示的只有<?php echo (D('House_village')->getHouseAlias('house_name',$village_id)?:'小区')?>导航，如果小于{pigcms{$show_nav_count}个则追加系统导航。</p>            <p>3.如果是关闭状态下，则无论<?php echo (D('House_village')->getHouseAlias('house_name',$village_id)?:'小区')?>里正常的导航有多少个都不会追加系统导航。</p>        </div>		<div id="nav" class="mainnav_title">			<ul>				<if condition="empty($_GET['frame_show'])">					<a href="{pigcms{:U('Library/index_nav_new')}">首页自定义导航列表</a>|				</if>				<a href="{pigcms{:U('Library/index_nav_new',$_GET)}" class="on">首页自定义导航列表</a>|                <if condition="($assign_type['type_2'] && $row_type eq '') || ($assign_type['type_11'] && $row_type eq single) || ($assign_type['type_13'] && $row_type eq middle)"><a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Library/nav_add_new',array('row_type' => $row_type))}','添加导航',850,580,true,false,false,addbtn,'add',true);">添加导航</a> </if>			</ul>		</div>		<div class="page_tips"><if condition="$row_type eq middle">图标建议尺寸：图片宽度建议为：200px，高度建议为：200px <else/> 图标建议尺寸：图片宽度建议为：150px，高度建议为：150px</if>        平台已为你添加<span>{pigcms{$adver_count}</span> 张</div>		<form name="myform" id="myform" action="" method="post">			<div class="table-list">				<table width="100%" cellspacing="0">					<thead>						<tr>							<th>编号</th>							<th>分类名称</th>							<th>排序</th><!--							<th>链接地址</th>--><!--							<th>图片(以下为强制小图，点击图片查看大图)</th>--><!--							<th class="textcenter">最后操作时间</th>-->							<th>状态</th>                            <if condition="($assign_type['type_2'] && $row_type eq '') || ($assign_type['type_11'] && $row_type eq single) || ($assign_type['type_13'] && $row_type eq middle)"><th class="textcenter">操作</th></if>						</tr>					</thead>					<tbody>						<if condition="is_array($result['list'])">							<volist name="result['list']" id="vo">								<tr>									<td>{pigcms{$vo.id}</td>									<td>{pigcms{$vo.name}</td>									<td>{pigcms{$vo.sort}</td><!--									<td><a href="{pigcms{$vo.url}" target="_blank">访问链接</a></td>--><!--									<td>--><!--										<img src="{pigcms{:file_domain()}/upload/adver/{pigcms{$vo.pic}" style="width:300px;height:80px;" class="view_msg"/>--><!--									</td>--><!--									<td class="textcenter">{pigcms{$vo.last_time|date='Y-m-d H:i:s',###}</td>-->									<td>									<if condition="$vo['status'] eq 1">										<font color="green">正常</font>									<elseif condition="$vo['status'] eq 0"/>										<font color="red">关闭</font>									</if></td>                                    <if condition="($assign_type['type_2'] && $row_type eq '') || ($assign_type['type_11'] && $row_type eq single) || ($assign_type['type_13'] && $row_type eq middle)">									<td class="textcenter">                                       <a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Library/nav_edit_new',array('id'=>$vo['id'],'from_page'=>$_GET['from_page']))}','编辑导航信息',850,580,true,false,false,editbtn,'add',true);">编辑</a> | <a href="javascript:void(0);" class="delete_row" parameter="id={pigcms{$vo.id}" url="{pigcms{:U('Library/nav_del_new')}">删除</a>                                    </td>                                    </if>								</tr>							</volist>						<else/>							<tr>                                <td class="textcenter red"  <if condition="($assign_type['type_2'] && $row_type eq '') || ($assign_type['type_11'] && $row_type eq single) || ($assign_type['type_13'] && $row_type eq middle)"> colspan="5" <else/>colspan="4"</if>>列表为空！</td>                            </tr>						</if>					</tbody>				</table>                {pigcms{$result.pagebar}			</div>		</form>	</div><style>    .table-list .summary {        margin: 10px 25px 5px 0 !important;        text-align: right !important;    }    .table-list .pager {        margin: 0 25px 5px 0 !important;        text-align: right !important;    }    .pager .next>a {        height: 30px;        line-height: 30px;    }    .pager .prev>a {        height: 30px;        line-height: 30px;    }</style><script>	let single = '{pigcms{$row_type}'    $("input[name=read_idcard]").change(function(){        var village_nav = $(this).val();      layer.confirm("是否保存显示系统导航设置?",{        btn: ['确认', '取消']      }, function () {        var url ="{pigcms{:U('set_village_nav')}";        $.post(url,{'village_nav': village_nav,'row_type': single},function(data){          layer.msg(data['msg'])        },'json')      }, function(){        if(village_nav == 1){          $("input[name=read_idcard][type=radio][value='0']").attr("checked",true);        }else{          $("input[name=read_idcard][type=radio][value='1']").attr("checked",true);        }      });    });	// 功能导航效果  $("input[name=multiline_effect]").change(function(){    var multiline_effect = $(this).val();    layer.confirm("是否保存功能导航效果?",{      btn: ['确认', '取消']    }, function () {      var url ="{pigcms{:U('set_village_nav')}";      $.post(url,{'multiline_effect': multiline_effect,'row_type': single},function(data){        layer.msg(data['msg'])      },'json')    }, function(){      if(multiline_effect == 1){        $("input[name=multiline_effect][type=radio][value='0']").attr("checked",true);      }else{        $("input[name=multiline_effect][type=radio][value='1']").attr("checked",true);      }    });  });  // 一屏展示数量  $("#view_num").change(function(){    var view_num = $("#view_num").val();    layer.confirm("是否保存一屏展示数量效果?",{      btn: ['确认', '取消']    }, function () {      var url ="{pigcms{:U('set_village_nav')}";      $.post(url,{'view_num': view_num,'row_type': single},function(data){        layer.msg(data['msg'])      },'json')    }, function(){      if(view_num == 5){        $("#view_num").attr('value',7);      }else{        $("#view_num").attr('value',5);      }    });  });</script><include file="Publics:footer"/>